{
  "contract": "SimpleSalesEth",
  "closure": {
    "site_function": "buy",
    "site_call": ".safeTransferFrom",
    "functions": [
      "buy",
      "withdrawAllFailedCredits"
    ],
    "justification": "These functions interact with _ethBal and failedTransferCredits, which are exposed during the callback."
  },
  "protocol": {
    "during_phase": "exposed",
    "allowed_callbacks": [
      "withdrawAllFailedCredits"
    ],
    "nesting_bound": {
      "buy": 1,
      "withdrawAllFailedCredits": 1
    }
  },
  "phases": {
    "function": "buy",
    "pre": {
      "name": "pre",
      "from_marker": "require(sales[_msgSender()] > 0);",
      "to_marker": "_ethBal += msg.value;"
    },
    "exposed": {
      "name": "exposed",
      "from_marker": "_ethBal += msg.value;",
      "to_marker": "require(success);"
    },
    "post": {
      "name": "post",
      "from_marker": "require(success);",
      "to_marker": "emit Purchase(_msgSender(), msg.value);"
    },
    "linearization_point": "emit Purchase(_msgSender(), msg.value);"
  },
  "ghost_state": [
    {
      "name": "inFlight",
      "sol_type": "uint256",
      "meaning": "Amount of ETH in transit during the callback window",
      "backed_by_storage": false
    }
  ],
  "exposure_invariant": {
    "formula": "_sum_failedTransferCredits == snapPre + inFlight",
    "stable_formula": "_sum_failedTransferCredits == snapPre",
    "kind": "conserve"
  },
  "composition": {
    "target_property": "_sum_failedTransferCredits <= _ethBal",
    "rule": "The sum of failedTransferCredits must always be less than or equal to the ETH balance."
  }
}
